<template>
  <AuthLayout :loading="processing" :showInfoPanel="false">
    <AuthCard
      :title="$t('forgot_password_header')"
      :success="success_message"
      :error="model['email_error_msg'] || ''"
    >
      <!-- Email input -->
      <q-input
        v-model="model['email']"
        dense
        outlined
        :label="$t('email')"
        class="w-full"
        :error="model['email_error']"
        hide-bottom-space
        @keyup.enter="enterS"
      />

      <!-- Recaptcha -->
      <div v-if="recaptcha_key" class="flex justify-center">
        <vue-recaptcha
          ref="recaptcha"
          :sitekey="recaptcha_key"
          @verify="captcaResp"
        />
      </div>

      <template #actions>
        <q-btn
          unelevated
          color="primary"
          text-color="white"
          :label="$t('resetBtn')"
          class="auth-submit-btn"
          @click="submitForm()"
          @keyup.enter="enterS"
        />
      </template>
    </AuthCard>

    <template #footer>
      <a
        class="text-sm text-primary cursor-pointer hover:underline"
        @click="user_login()"
      >{{ $t('back_to_login') }}</a>
    </template>
  </AuthLayout>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import axios from 'axios';
import { defineComponent, ref } from 'vue';
import { VueRecaptcha } from 'vue-recaptcha';
import type { dynamicObj } from 'src/pages/assets';
import helperUtil from 'src/utils/helperUtil';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
import { LocalStorage, SessionStorage } from 'quasar';
import { api, getClientAuthorization } from 'pages/APIs';
import { AuthLayout, AuthCard } from 'src/components/Auth';
import { CONSTANTS } from 'src/constants';

export default defineComponent({
  mixins: [helperMixin, helperUtil],
  components: {
    VueRecaptcha,
    AuthLayout,
    AuthCard,
  },
  setup() {
    return {
      model: ref({} as { [k: string]: any }),
      processing: ref(false),
      recaptcha_key: ref(''),
      captchaResponse: ref(''),
      error_message: ref(''),
      success_message: ref(''),
    };
  },
  mounted() {
    this.setNewModel();
    this.setRecaptchaKey();
  },
  methods: {
    enterS() {
      this.submitForm();
    },

    setNewModel() {
      this.model['email'] = '';
      this.resetErrors();
    },

    resetErrors() {
      this.model['email_error_msg'] = '';
      this.model['email_error'] = false;
    },

    setRecaptchaKey() {
      if (!process.env.APP_VUE_RECAPTCHA_KEY) {
        logInfo('Recaptcha key is missing');
        return;
      }
      this.recaptcha_key = process.env.APP_VUE_RECAPTCHA_KEY;
    },

    captcaResp(captResponse: any) {
      this.captchaResponse = captResponse;
    },

    user_login() {
      this.$router.push('/');
    },

    async submitForm() {
      try {
        if (!this.validateRow()) return;
        this.processing = true;
        let formData = new FormData();
        formData.append('email', this.model['email']);
        formData.append('captcha_response', this.captchaResponse);
        const response = await axios.post(api.forget_password, formData, {
          headers: {
            'Content-Type': 'application/x-www-form-urlencoded',
            Authorization: getClientAuthorization(),
          },
        });
        if (!response || !response.data) throw response;
        if (!response.data.success) throw response;

        this.success_message = response.data.message;
        this.setNewModel();
      } catch (err: any) {
        this.handleErrors(err);
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
        this.resetRecaptcha();
      }
    },

    validateRow() {
      let error = false;
      this.resetErrors();

      if (!this.model['email'] || this.model['email'].length == 0) {
        error = true;
        this.model['email_error_msg'] = this.$t('email_required');
        this.model['email_error'] = true;
      }
      let isEmailValid = this.validateEmail(this.model['email']);
      if (error === false && !isEmailValid) {
        error = true;
        this.model['email_error_msg'] = this.$t('email_invalid');
        this.model['email_error'] = true;
      }

      return !error;
    },

    handleErrors(error: any) {
      let msg = '';
      if (
        error != null &&
        typeof error == 'object' &&
        error.hasOwnProperty('message')
      ) {
        msg = error.response.data.error_code;
      }
      if (!msg || msg === '') return;

      this.model['email_error_msg'] = this.$t(msg);
      this.model['email_error'] = true;
      throw { message: msg };
    },

    resetRecaptcha() {
      try {
        (<any>this).$refs['recaptcha'].reset();
      } catch (err: any) {
        logError(err);
      }
    },
  },
});
</script>

<style scoped lang="scss">
.auth-submit-btn {
  width: 100%;
  height: 44px;
  font-weight: 500;
  border-radius: 0.5rem;
}
</style>
